```javascript
adjustSynchronization(currentTime, maxSpeedControl) {
    // Garante que a chamada passe uma referência ou valor explícito ao controlador
    const maxSpeed = parseFloat(maxSpeedControl.value) || 0;

    const speechQueue = this.speechQueue;
    if (!speechQueue || speechQueue.length === 0) return;

    const nextSpeechTime = speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    switch (this.dubbingMode) {
        case 'advanced':
            if (timeDifference < 0) {
                // Dublagem está adiantada
                const expectedTime = nextSpeechTime;
                const delayTime = currentTime - expectedTime;

                // Ajuste gradual da velocidade
                const speedDelta = Math.min(0.2, Math.abs(this.userConfiguredSpeed - 1.2));
                this.speedControl.value = Math.min(maxSpeed, 1.2 + speedDelta);
                this.webtoonSpeakingRateControl.setStereoSpeakingRate(this.speedControl.value);

                // Controle visual do atraso
                this.delayDisplay.value = Math.max(0, Math.abs(delayTime));
                this.updateRangeValue('speed');

            } else if (timeDifference > 0) {
                // Dublagem está atrasada
                const speechDelay = timeDifference;
                const targetSpeed = Math.max(this.userConfiguredSpeed, 0.5); // Reserva mínimo de 0.5
                const audioSpeakingRate = this.webtoonSpeakingRateControl.getStereoSpeakingRate();

                // Ajuste à velocidade da fala
                let adjustedSpeed = audioSpeakingRate;

                if (speedSettings.advancedSpeechLengthAdjustment) {
                    const lengthAdjustment = this.speedControl.value - 1.0;
                    adjustedSpeed = 1.0 + (lengthAdjustment * (maxSpeed - 1.2));
                }

                this.speedControl.value = Math.max(targetSpeed, adjustedSpeed);
                this.webtoonSpeakingRateControl.setStereoSpeakingRate(adjustedSpeed);
                this.updateRangeValue('speed');

                // Controle visual da antecipação
                this.advanceDisplay.value = Math.min(1000, 1000 + speedDelta);
                this.speedDisplay.value = speedDelta.toFixed(1);
                this.updateRangeValue('speed');
            }
            break;

        case 'normal':
            if (this.dubbedTime < currentTime) {
                // Ajuste para voltar à sincronização
                const speedAdjustment = (this.userConfiguredSpeed - 1.2) / 1.0;
                this.speedControl.value = Math.max(this.userConfiguredSpeed, 0.8);
                if (this.dubbingMode == 'advanced' && this.maxSpeechDurationControl) {
                    this.maxSpeedControl.value = Math.min(this.maxSpeedControl.value || 3.0, this.userConfiguredSpeed + speedAdjustment);
                    const duration = this.dubbingLogitControl.getSereoverDuration();
                    this.updateRangeValue('maxSpeed');
                }
            }
            break;
    }
}
```

